import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import AjvModule from "ajv";
import addFormatsModule from "ajv-formats";
import standaloneCode from "ajv/dist/standalone/index.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(__dirname, "..");
const goldenPath = join(repoRoot, "test/fixtures/physio-mcp-tools.golden.json");
const outPath = join(repoRoot, "src/services/mcp/generated/input-validators.js");

const banner = `/* eslint-disable */
/* Generated by scripts/generate-mcp-input-validators.mjs — do not edit by hand. */
`;

function buildGeneratedSource() {
  const golden = JSON.parse(readFileSync(goldenPath, "utf8"));

  const Ajv = AjvModule.default ?? AjvModule;
  const addFormats = addFormatsModule.default ?? addFormatsModule;
  const ajv = new Ajv({
    allErrors: true,
    strict: false,
    validateFormats: true,
    validateSchema: false,
    code: { source: true, esm: true },
  });
  addFormats(ajv);

  const refs = {};
  for (const tool of golden) {
    const id = `physio-mcp-input/${tool.name}`;
    ajv.addSchema({ ...tool.inputSchema, $id: id });
    refs[tool.name] = id;
    ajv.compile({ $ref: id });
  }

  return `${banner}${standaloneCode(ajv, refs)}`;
}

const checkMode = process.argv.includes("--check");
const generated = buildGeneratedSource();

if (checkMode) {
  const committed = readFileSync(outPath, "utf8");
  if (committed !== generated) {
    console.error(
      "Generated MCP input validators are out of date. Run: node scripts/generate-mcp-input-validators.mjs",
    );
    process.exit(1);
  }
  process.exit(0);
}

writeFileSync(outPath, generated, "utf8");
